// COLLECTOR_MODE 0: keyword spotting on the ESP32.
//
// Every KWS_HOP_MS the last 1 s of audio becomes a log-mel spectrogram (exactly like the
// trainer: constants in features.h, generated by trainer/export.py), the TFLite Micro model
// (model_data.h) classifies it, KWS_AVERAGE results are averaged, and a command whose
// average reaches KWS_THRESHOLD is reported once (then KWS_REFRACTORY_MS of silence).
#pragma once

namespace kws {

using CommandHandler = void (*)(const char *label, float confidence);

bool begin(CommandHandler handler);  // false: printed why on Serial
void step();                         // call from loop()

}  // namespace kws
